import {componentDetails} from './component-details.js';
import {resolvePanelCut} from './panel-cut.js';
import {fallRegions,fallFoldLines} from './fall-regions.js';
import {worldPath,samples,polyD,bounds,uniform,offsetPoints,makePath,uid,pathD} from './core.js';
import {contours,offsetClosed,clipLines,booleanPaths} from './geometry.js';
const part=(d,m,extra={})=>({d,stroke:m.stroke||'#252a29',width:m.thickness??.8,fill:'none',...extra});
const rng=(i,seed)=>{const x=Math.sin(i*127.1+(seed||1)*311.7)*43758.5453;return x-Math.floor(x);};
const cache=new Map();
export function garmentParts(o,m){const key=JSON.stringify([o.nodes,o.closed,o.matrix,o.component,o.modifiers,o.subpaths,m]);if(cache.has(key))return cache.get(key);const result=generate(o,m);if(cache.size>150)cache.clear();cache.set(key,result);return result;}
function generate(o,m){const rings=contours(o),b=bounds(o),inset=Math.max(0,m.inset??3),inside=inset?offsetClosed(rings,-inset):rings;if(!inside.length)return [];let lines=[];
if(m.type==='fabricFall'){const regions=fallRegions(o,m);if(regions.length){const matrix=o.matrix;lines=fallFoldLines(regions,m).map(line=>line.map(p=>({x:matrix[0]*p.x+matrix[2]*p.y+matrix[4],y:matrix[1]*p.x+matrix[3]*p.y+matrix[5]})));return clipLines(lines,inside).map(line=>part(polyD(line),m));}const count=Math.max(0,Math.min(12,Math.round(m.foldCount??3))),extent=Math.min(b.h,m.length??70),start=b.y+b.h-extent;for(let i=1;i<=count;i++){const y=start+extent*i/(count+1),tilt=(rng(i,m.seed)-.5)*(m.irregularity??.3)*extent*.3;lines.push([{x:b.x-1,y:y+tilt},{x:b.x+b.w*.3,y:y-2},{x:b.x+b.w*.65,y:y+3},{x:b.x+b.w+1,y:y-tilt}]);}return clipLines(lines,inside).map(line=>part(polyD(line),m));}
if(m.type==='quilt'||m.type==='pleat'){const spacing=Math.max(3,m.spacing??m.pleatWidth??18),pattern=m.pattern||'horizontal',angles=m.type==='pleat'?[m.direction==='horizontal'?0:90]:pattern==='grid'?[0,90]:pattern==='diamond'?[45,135]:[pattern==='vertical'?90:0],radius=Math.hypot(b.w,b.h)+10,cx=b.x+b.w/2,cy=b.y+b.h/2;for(const deg of angles){const a=(deg+(m.angle||0))*Math.PI/180,u={x:Math.cos(a),y:Math.sin(a)},v={x:-u.y,y:u.x};for(let s=-radius,n=0;s<radius&&n<800;s+=spacing,n++){lines.push([{x:cx+v.x*s-u.x*radius,y:cy+v.y*s-u.y*radius},{x:cx+v.x*s+u.x*radius,y:cy+v.y*s+u.y*radius}]);if(m.type==='pleat'){const depth=m.depth??4,side=m.pleatType==='box'?-depth:depth;lines.push([{x:cx+v.x*(s+side)-u.x*radius,y:cy+v.y*(s+side)-u.y*radius},{x:cx+v.x*(s+side)+u.x*radius,y:cy+v.y*(s+side)+u.y*radius}]);}}}if(m.type==='pleat'&&m.count)lines=lines.slice(Math.floor(lines.length/2),Math.floor(lines.length/2)+Math.min(80,m.count)*2);return clipLines(lines,inside).map(line=>part(polyD(line),m));}
if(m.type==='distress'){const count=Math.min(80,m.count??8);for(let i=0;i<count;i++){const x=b.x+rng(i*3,m.seed)*b.w,y=b.y+rng(i*3+1,m.seed)*b.h,len=(m.length??12)*(0.5+rng(i*3+2,m.seed));lines.push([{x,y},{x:x+len,y:y+(m.direction==='vertical'?len:2)}]);}return clipLines(lines,inside).map(line=>part(polyD(line),m));}return [];}
export function componentParts(o,evaluateEffect){const c=o.component;if(!c)return [];const zip=c.kind==='pocket'&&['zip','diagonalZip'].includes(c.style)&&evaluateEffect,result=componentDetails(o,{zip:!zip});if(zip){const w=c.width,y=c.zipPosition??25,angle=(c.openingAngle||0)*Math.PI/180,guide=makePath('Abertura de bolsillo',`M 7 ${y} L ${w-7} ${y+Math.tan(angle)*(w-14)}`);guide.matrix=o.matrix;result.push(...evaluateEffect({type:'zipper',stroke:o.stroke,width:.65,zipWidth:3,tapeWidth:1,teeth:2,teethSpacing:3,teethWidth:1.5,slider:.08,openAmount:0},guide));}return result;}
export function splitPanel(region,boundary){const result=resolvePanelCut(region,boundary);if(!result.valid)throw Error(result.diagnostics.message);return result.regions;}
